44	  /// Pattern of lldb log when the process is stopped.
45	  ///
46	  /// Example: (lldb) Process 6152 stopped
47	  static final _lldbProcessStopped = RegExp(r'Process \d* stopped');
48	
49	  /// Pattern of lldb log when the process is resuming.
50	  ///
51	  /// Example: (lldb) Process 6152 resuming
52	  static final _lldbProcessResuming = RegExp(r'Process \d+ resuming');
53	
54	  /// Pattern of lldb log when the breakpoint is added.
55	  ///
56	  /// Example: Breakpoint 1: no locations (pending).
57	  static final _breakpointPattern = RegExp(r'Breakpoint (\d+)*:');
