64	  /// This should match the "handle_new_rx_page" function in [IosProject._lldbPythonHelperTemplate].
65	  static const _pythonScript = '''
66	"""Intercept NOTIFY_DEBUGGER_ABOUT_RX_PAGES and touch the pages."""
67	base = frame.register["x0"].GetValueAsAddress()
68	page_len = frame.register["x1"].GetValueAsUnsigned()
69	
70	# Note: NOTIFY_DEBUGGER_ABOUT_RX_PAGES will check contents of the
71	# first page to see if handled it correctly. This makes diagnosing
72	# misconfiguration (e.g. missing breakpoint) easier.
73	data = bytearray(page_len)
74	data[0:8] = b'IHELPED!'
75	
76	error = lldb.SBError()
77	frame.GetThread().GetProcess().WriteMemory(base, data, error)
78	if not error.Success():
79	    print(f'Failed to write into {base}[+{page_len}]', error)
80	    return
81	''';
